code_examples.vulnerable:
class UserObj {
    #privArray = [];

    // private 배열을 리턴하는 public 메소드를 사용하는 경우 취약
    get_private_member = () => {
        return this.#privArray;
    }
}

code_examples.safe:
class UserObj {
    #privArray = [];

    // private 배열을 반환하는 경우 복사본을 사용해 외부와 내부의
    // 배열이 서로 참조되지 않도록 해야 함
    get_private_member = () => {
        const copied = Object.assign([], this.#privArray);
        return copied;
    }
}
